  rocq_int63::ltb(v0, v1)
}

// Rocq: Nonnegpartsums.nonnegpartsums_implem.bdec
pub fn bdec(b: bool) -> sumbool {
  if b {
    sumbool::left
  } else {
    sumbool::right
  }
}

