// Rocq: Nonnegpartsums.nonnegpartsums_implem.prefix_loop
// Variant: uncurried
pub fn prefix_loop_1(x: Rc<Array<u64>>, n: u64, i: u64, P: Rc<Array<u64>>) -> Rc<Array<u64>> {
  prefix_loop(x, n, i, P, ())
