// Rocq: Nonnegpartsums.nonnegpartsums_implem.qv
// Variant: uncurried
pub fn qv(P: Rc<Array<u64>>, n: u64, tot: u64, j: u64) -> u64 {
  if leb(j, n) {
    let tmp = rocq_array::get::<u64>(&P, j);
    std::mem::drop(P);
    tmp
  } else {
    let tmp_1 = rocq_array::get::<u64>(&P, sub(j, n));
    std::mem::drop(P);
    add(tot, tmp_1)
  }
}

